        }

        public init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            items = try container.decodeIfPresent([TodoItem].self, forKey: .items) ?? []
        }
    }
    public struct Mcp: Codable, Hashable, Sendable {
        public var server: String
        public var tool: String
        public var input: JSONValue?

        public init(server: String, tool: String, input: JSONValue? = nil) {
            self.server = server
            self.tool = tool
            self.input = input
        }

        enum CodingKeys: String, CodingKey {
            case server
            case tool
            case input
        }
    }
    public struct Unknown: Codable, Hashable, Sendable {
        public var name: String
        public var input: JSONValue?

        public init(name: String, input: JSONValue? = nil) {
            self.name = name
            self.input = input
        }

        enum CodingKeys: String, CodingKey {
            case name
            case input
        }
    }

    public init(from decoder: Decoder) throws {
        let kind = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: TagKey("kind"))
        switch kind {
        case "exec": self = .exec(try Exec(from: decoder))
        case "readFile": self = .readFile(try ReadFile(from: decoder))
        case "writeFile": self = .writeFile(try WriteFile(from: decoder))
        case "editFile": self = .editFile(try EditFile(from: decoder))
        case "applyPatch": self = .applyPatch(try ApplyPatch(from: decoder))
        case "search": self = .search(try Search(from: decoder))
        case "glob": self = .glob(try Glob(from: decoder))
        case "webFetch": self = .webFetch(try WebFetch(from: decoder))
        case "webSearch": self = .webSearch(try WebSearch(from: decoder))
        case "todo": self = .todo(try Todo(from: decoder))
        case "mcp": self = .mcp(try Mcp(from: decoder))
        case "unknown": self = .unknown(try Unknown(from: decoder))
        default: self = .unrecognized(kind: kind)
        }
    }

    public func encode(to encoder: Encoder) throws {
        var tag = encoder.container(keyedBy: TagKey.self)
        switch self {
        case .exec(let payload): try tag.encode("exec", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .readFile(let payload): try tag.encode("readFile", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .writeFile(let payload): try tag.encode("writeFile", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .editFile(let payload): try tag.encode("editFile", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .applyPatch(let payload): try tag.encode("applyPatch", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .search(let payload): try tag.encode("search", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .glob(let payload): try tag.encode("glob", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .webFetch(let payload): try tag.encode("webFetch", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .webSearch(let payload): try tag.encode("webSearch", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .todo(let payload): try tag.encode("todo", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .mcp(let payload): try tag.encode("mcp", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .unknown(let payload): try tag.encode("unknown", forKey: TagKey("kind")); try payload.encode(to: encoder)
        case .unrecognized(let kind): try tag.encode(kind, forKey: TagKey("kind"))
        }
    }
}

