public enum TranscriptFrame: Codable, Hashable, Sendable {
    case reset(Reset)
    case delta(Delta)

    public struct Reset: Codable, Hashable, Sendable {
        public var reset: [SessionMessageEntry]

        public init(reset: [SessionMessageEntry]) {
            self.reset = reset
        }

        enum CodingKeys: String, CodingKey {
            case reset
        }
    }
    public struct Delta: Codable, Hashable, Sendable {
        public var upsert: [TranscriptUpsert]
        public var append: [TextAppend]
        public var remove: [String]
        public var count: Int

        public init(upsert: [TranscriptUpsert] = [], append: [TextAppend] = [], remove: [String] = [], count: Int) {
            self.upsert = upsert
            self.append = append
            self.remove = remove
            self.count = count
        }

        enum CodingKeys: String, CodingKey {
            case upsert
            case append
            case remove
            case count
        }

        public init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            upsert = try container.decodeIfPresent([TranscriptUpsert].self, forKey: .upsert) ?? []
            append = try container.decodeIfPresent([TextAppend].self, forKey: .append) ?? []
            remove = try container.decodeIfPresent([String].self, forKey: .remove) ?? []
            count = try container.decode(Int.self, forKey: .count)
        }
    }

    public init(from decoder: Decoder) throws {
        if let payload = try? Reset(from: decoder) { self = .reset(payload); return }
        if let payload = try? Delta(from: decoder) { self = .delta(payload); return }
        throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "no TranscriptFrame variant matched"))
    }

    public func encode(to encoder: Encoder) throws {
        switch self {
        case .reset(let payload): try payload.encode(to: encoder)
        case .delta(let payload): try payload.encode(to: encoder)
        }
    }
}

